arguments.command:
cd /tmp/sv-7e1a2876d18445f5ae52a032c56ab47e/moderate-version-conflicts && dotnet package list --format json 2>/dev/null | python3 -m json.tool > after-cpm-packages.json && python3 -c "
import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def pkg_map(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-2]
        for fw in proj['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

b = pkg_map(baseline)
a = pkg_map(after)
changes = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    if bv != av:
        changes.append(f'{key[0]:10s} {key[1]:40s} {bv:10s} -> {av}')
if changes:
    print('CHANGES:')
    for c in changes: print(c)
else:
    print('No unexpected changes')

# Show all unchanged
unchanged = [(k,b[k]) for k in sorted(b.keys()) if b.get(k) == a.get(k)]
print(f'\nUnchanged: {len(unchanged)} package references')
"

